import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.CZqXuAiL.js";const g=JSON.parse('{"title":"Upgrade","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/getting-started/upgrade.md","filePath":"openshield-xdp/getting-started/upgrade.md","lastUpdated":null}'),o={name:"openshield-xdp/getting-started/upgrade.md"};function n(d,e,l,r,c,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h1><h2 id="upgrading-from-1-9-x-to-2-1-x" tabindex="-1">Upgrading from 1.9.x to 2.1.x <a class="header-anchor" href="#upgrading-from-1-9-x-to-2-1-x" aria-label="Permalink to &quot;Upgrading from 1.9.x to 2.1.x&quot;">​</a></h2><p>v2.0 → v2.1.1 is a feature-heavy jump. The upgrade path is the standard one (<code>git pull &amp;&amp; sudo ./install.sh --update</code>, or <code>sudo openshield upgrade</code>), but here&#39;s what changes behavior and what&#39;s worth reconfiguring.</p><h3 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h3><ul><li><strong>Established-connection exemption</strong> (<code>static.ct_established_exempt</code>, default <code>true</code>) — sources with a proven TCP session are exempt from PPS/BPS/TCP scoring. Bulk uploads (SFTP, backups) no longer get banned.</li><li><strong>Per-port threshold overrides</strong> (<code>static.port_thresholds</code>, max 8) — per-port/range PPS/BPS limits that replace the globals, in peacetime and attack mode.</li><li><strong>Attack per-port cap</strong> (<code>dynamic.attack_port_pps</code>) — aggregate per-destination-port PPS cap during declared attacks. Rotation-proof against spoofed floods; legit traffic on the port is throttled, not banned.</li><li><strong>New-source floods now temp-ban</strong> each excess new source for <code>dynamic.new_source_ban_duration</code> seconds (previously dropped only one packet — useless against rotation).</li><li><strong>Behavior engine auto-block</strong> (<code>behavior.auto_block</code>, default <code>true</code> since 2.1.0) — lookalike bot clusters at ≥85% confidence are auto-banned for 1 hour. Set <code>false</code> for report-only mode.</li><li><strong>Metrics API</strong> (<code>metrics:</code> section, default off) — HTTP JSON endpoint with everything the TUI shows. Manage the key with <code>openshield key</code> / <code>key set</code> / <code>key regen</code>.</li><li><strong>CLI aliases</strong> — <code>st</code>, <code>wl</code>, <code>bl</code>, <code>lic</code>, <code>cfg</code>, <code>dash</code>.</li><li><strong>Whitelist persistence</strong> — <code>openshield whitelist add/remove</code> now writes through to the YAML config and survives loader restarts.</li><li><strong>Richer forensics</strong> — attack bundles now include <code>config_snapshot.txt</code> and <code>config_changes.txt</code>.</li><li><strong><code>openshield uninstall</code></strong> — clean removal (also <code>uninstall.sh</code>).</li></ul><h3 id="what-to-reconfigure" tabindex="-1">What to reconfigure <a class="header-anchor" href="#what-to-reconfigure" aria-label="Permalink to &quot;What to reconfigure&quot;">​</a></h3><ul><li><strong>Preset scoring was retuned in 2.1.1.</strong> Single-source floods that were mathematically unbannable on the Gaming/Hosting/Performance/CDN presets now get banned in seconds. <strong>Existing installs keep their old values</strong> — run <code>sudo openshield reconfigure</code> to pick up the retuned numbers (or edit scores manually).</li><li>New config sections get defaults automatically; you don&#39;t have to add them by hand. Generate an annotated reference with <code>sudo openshield config</code> if you want to see every new key.</li><li>If you previously worked around upload bans with high global thresholds, you can now tighten globals back down and rely on <code>ct_established_exempt</code> + <code>port_thresholds</code> instead.</li></ul><h3 id="license-note" tabindex="-1">License note <a class="header-anchor" href="#license-note" aria-label="Permalink to &quot;License note&quot;">​</a></h3><p>Your existing license key is untouched by the upgrade — it lives in <code>/etc/openshield/openshield.yaml</code> (<code>license.key</code>) with its cache at <code>/var/lib/openshield/license.json</code>, both of which survive. No reactivation is needed. If a fresh install asks for a key, use <code>sudo openshield license activate &lt;key&gt;</code> or <code>openshield lic status</code> to check state.</p><h2 id="between-versions" tabindex="-1">Between versions <a class="header-anchor" href="#between-versions" aria-label="Permalink to &quot;Between versions&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OpenShield-XDP</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Config struct changes</p><p>When upgrading between versions that change the <code>config</code> struct, stale pinned maps must be cleared. The installer handles this automatically. If you upgrade manually, run <code>sudo openshield fix</code> before loading.</p></div><h2 id="openshield-upgrade-command-experimental" tabindex="-1"><code>openshield upgrade</code> command (EXPERIMENTAL) <a class="header-anchor" href="#openshield-upgrade-command-experimental" aria-label="Permalink to &quot;\`openshield upgrade\` command (EXPERIMENTAL)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Performs a 5-step automated upgrade:</p><ol><li><code>git pull</code> (or <code>git clone</code> if no repo found)</li><li><code>make ebpf</code> — rebuild BPF programs</li><li><code>make generate</code> — regenerate bpf2go Go bindings</li><li><code>make userspace</code> — rebuild Go binaries</li><li>Stop loader → install new binaries → restart</li></ol><div class="danger custom-block"><p class="custom-block-title">Security caveat</p><p><code>openshield upgrade</code> runs <code>git clone</code> and <code>make</code> as <strong>root</strong>. This is comparable to any package manager — but the upgrade pulls from GitHub and executes a build pipeline with root privileges. For production environments, prefer the manual <code>git pull &amp;&amp; sudo ./install.sh --update</code> workflow, which lets you inspect changes before installing.</p></div><h2 id="rolling-back" tabindex="-1">Rolling back <a class="header-anchor" href="#rolling-back" aria-label="Permalink to &quot;Rolling back&quot;">​</a></h2><p>Git tags mark stable releases. To roll back:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><h2 id="what-survives-an-upgrade" tabindex="-1">What survives an upgrade <a class="header-anchor" href="#what-survives-an-upgrade" aria-label="Permalink to &quot;What survives an upgrade&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Survives</th></tr></thead><tbody><tr><td>Active bans</td><td>Yes (pinned maps persist)</td></tr><tr><td>Subnet bans</td><td>Yes</td></tr><tr><td>Whitelist</td><td>Repopulated from YAML</td></tr><tr><td>Configuration</td><td>Kept unless config format changed</td></tr><tr><td>IP statistics</td><td>Cleared (fresh start)</td></tr><tr><td>Baseline (EMA)</td><td>Restored from <code>baseline.json</code></td></tr><tr><td>Per-IP SYN counters</td><td>Cleared (fresh start; rate-based SYN gate re-learns)</td></tr></tbody></table><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>After upgrading, confirm the program loaded correctly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Verify config is valid</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/">User Guide</a> — setup and tuning in plain language</li><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/configuration">Configuration</a></li><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/cli">CLI Reference</a></li></ul>`,27)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
